// Built-in character registry (plan M-ART MA-10): lists resources/characters/<id>/ (generated by `pnpm sprites`),
// validates each manifest with the same zod schema imported packs will use (dogfooding), checks the atlas header
// against the strips and keeps only valid packs. `spike-*` packs (art spike) are listed only when unpackaged, or
// for the perf harness (`--perf-spike`), which copies one spike pack into the unpacked build itself.
import { closeSync, fstatSync, lstatSync, openSync, readdirSync, readSync, realpathSync } from 'node:fs';
import { isAbsolute, join, relative } from 'node:path';
import { checkStrips, manifestSchema, PACK_ID, type Manifest } from '../../shared/pack.ts';

/** Built-in atlases are smaller than the import limit (rules/render.md). */
export const BUILTIN_ATLAS_MAX = 2048;
const MANIFEST_MAX_BYTES = 64 * 1024;

export interface CharacterPack {
  readonly id: string;
  readonly dir: string;
  readonly manifest: Manifest;
  /** The one atlas every animation of a built-in pack lives in (relative, `sprites/…`). */
  readonly atlas: string;
}

export interface RegistryResult {
  readonly packs: ReadonlyMap<string, CharacterPack>;
  readonly errors: readonly string[];
}

export interface RegistryOptions {
  readonly includeSpike: boolean;
}

export const isSpikePack = (id: string): boolean => id.startsWith('spike-');

/** Width and height from a PNG signature + IHDR (first 24 bytes), or undefined if it is not a PNG. */
export function pngSize(head: Uint8Array): { width: number; height: number } | undefined {
  const sig = [0x89, 0x50, 0x4e, 0x47, 0x0d, 0x0a, 0x1a, 0x0a];
  const buf = Buffer.from(head.buffer, head.byteOffset, head.byteLength);
  if (buf.length < 24 || sig.some((b, i) => buf[i] !== b) || buf.toString('latin1', 12, 16) !== 'IHDR') {
    return undefined;
  }
  return { width: buf.readUInt32BE(16), height: buf.readUInt32BE(20) };
}

/**
 * Reads up to `length` bytes (or the whole file, capped by `maxBytes`) of a regular, non-symlink file whose real path
 * stays inside the real `root` (junctions/links on any segment resolved). Size check and read use one handle, so
 * the file cannot be swapped between them.
 */
export function readContainedSync(root: string, file: string, maxBytes: number, length?: number): Buffer {
  if (lstatSync(file).isSymbolicLink()) throw new Error(`${file} is a link`);
  const real = realpathSync(file);
  const rel = relative(realpathSync(root), real);
  if (rel === '' || rel.startsWith('..') || isAbsolute(rel)) throw new Error(`${file} resolves outside the pack root`);
  const fd = openSync(real, 'r');
  try {
    const info = fstatSync(fd);
    if (!info.isFile()) throw new Error(`${file} is not a file`);
    if (length === undefined && info.size > maxBytes) throw new Error(`${file} is too large`);
    const size = length === undefined ? info.size : Math.min(length, info.size);
    const bytes = Buffer.alloc(size);
    const read = readSync(fd, bytes, 0, size, 0);
    return bytes.subarray(0, read);
  } finally {
    closeSync(fd);
  }
}

function loadPack(root: string, id: string): CharacterPack {
  const dir = join(root, id);
  if (lstatSync(dir).isSymbolicLink()) throw new Error('the pack folder is a link');
  const manifestPath = join(dir, 'manifest.json');
  const raw = readContainedSync(root, manifestPath, MANIFEST_MAX_BYTES).toString('utf8');
  const parsed = manifestSchema.safeParse(JSON.parse(raw));
  if (!parsed.success) throw new Error(`invalid manifest: ${parsed.error.issues.map((i) => i.message).join('; ')}`);
  const manifest = parsed.data;
  if (manifest.id !== id) throw new Error(`manifest id "${manifest.id}" does not match its folder`);
  const files = new Set(Object.values(manifest.animations).map((a) => a.file));
  const [atlas] = [...files];
  if (files.size !== 1 || atlas === undefined) throw new Error('a built-in pack keeps every animation in one atlas');
  const size = pngSize(readContainedSync(root, join(dir, atlas), 0, 24));
  if (!size) throw new Error(`${atlas} is not a PNG`);
  const problems = checkStrips(manifest, new Map([[atlas, size]]), BUILTIN_ATLAS_MAX);
  if (problems.length > 0) throw new Error(problems.join('; '));
  return { id, dir, manifest, atlas };
}

export function loadRegistry(root: string, options: RegistryOptions): RegistryResult {
  const packs = new Map<string, CharacterPack>();
  const errors: string[] = [];
  let names: string[];
  try {
    names = readdirSync(root, { withFileTypes: true })
      .filter((d) => d.isDirectory() && !d.isSymbolicLink())
      .map((d) => d.name)
      .sort();
  } catch {
    return { packs, errors: [`no character folder at ${root}`] };
  }
  for (const id of names) {
    if (!PACK_ID.test(id) || (isSpikePack(id) && !options.includeSpike)) continue;
    try {
      packs.set(id, loadPack(root, id));
    } catch (error) {
      errors.push(`${id}: ${error instanceof Error ? error.message : String(error)}`);
    }
  }
  return { packs, errors };
}
